// Get returns the record addressed by its resource name.
func (r *GraphQLEventRepository) Get(ctx context.Context, name string) (*eventv1.Event, error) {
	ids, err := repox.SplitName(name, "events")
	if err != nil {
		return nil, err
	}
	return r.get(ctx, ids[len(ids)-1])
}

// rowID returns the surrogate key of the row named name: its bare id.
func (r *GraphQLEventRepository) rowID(_ context.Context, name string) (string, error) {
	ids, err := repox.SplitName(name, "events")
	if err != nil {
		return "", err
	}
	return ids[len(ids)-1], nil
}

// get loads by surrogate key — the private read every generated method
// re-reads through.
func (r *GraphQLEventRepository) get(ctx context.Context, id string) (*eventv1.Event, error) {
	row, err := r.Svc.Query.Event.Resource.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return r.toProto(ctx, row, nil)
}

