// List returns one page of records.
func (r *GraphQLEventRepository) List(ctx context.Context, in repox.ListInput) ([]*eventv1.Event, string, error) {
	return r.list(ctx, in)
}

func (r *GraphQLEventRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*eventv1.Event, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, resourceql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*eventv1.Event)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[resourceql.EventResource](event.EventFilterSpec, r.Svc.Query.Event.Resource).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	eng.Via("attendee_info", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Event.AttendeeInfos.List(ctx, attendeeinfosql.List().Where(graphql.And(attendeeinfosql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*eventv1.Event, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

// Update persists the masked fields of in; an empty mask replaces every
// mutable field. When in.Etag is set the write is guarded server-side
// (UpdateIfMatch); a stale etag returns repox.ErrConflict.
func (r *GraphQLEventRepository) Update(ctx context.Context, in *eventv1.Event, paths []string) (*eventv1.Event, error) {
	return r.update(ctx, in, paths, nil)
}

// UpdateWithOutputOnly is Update plus the server-owned fields outputPaths
// names, in the same patch and under the same guard.
func (r *GraphQLEventRepository) UpdateWithOutputOnly(ctx context.Context, in *eventv1.Event, paths, outputPaths []string) (*eventv1.Event, error) {
	return r.update(ctx, in, paths, outputPaths)
}

